using System;
class Benchmark {
    static long Fibonacci(int number) => number < 2 ? number : Fibonacci(number - 1) + Fibonacci(number - 2);
    static long FibonacciIterative(int number) { long previous = 0, current = 1; for (var index = 0; index < number; index++) (previous, current) = (current, previous + current); return previous; }
    static int CountPrimes(int limit) { var prime = new bool[limit + 1]; Array.Fill(prime, true); prime[0] = prime[1] = false; for (var number = 2; number * number <= limit; number++) if (prime[number]) for (var multiple = number * number; multiple <= limit; multiple += number) prime[multiple] = false; var count = 0; foreach (var value in prime) if (value) count++; return count; }
    static void Main(string[] args) { var fibonacciInput = args.Length > 0 ? int.Parse(args[0]) : 37; var primeLimit = args.Length > 1 ? int.Parse(args[1]) : 2000000; var numericIterations = args.Length > 2 ? int.Parse(args[2]) : 100000; var watch = System.Diagnostics.Stopwatch.StartNew(); var fr = Fibonacci(fibonacciInput); watch.Stop(); var ft = watch.Elapsed.TotalSeconds; watch.Restart(); var pr = CountPrimes(primeLimit); watch.Stop(); var pt = watch.Elapsed.TotalSeconds; watch.Restart(); long numericResult = 0; for (var iteration = 0; iteration < numericIterations; iteration++) numericResult += FibonacciIterative(fibonacciInput); watch.Stop(); if (numericResult < 0) throw new InvalidOperationException(); Console.WriteLine($"{ft:F6},{pt:F6},{watch.Elapsed.TotalSeconds:F6},{fr},{pr},{numericResult}"); }
}
